11	/*!
12	 * \file add_example_tiling.cpp
13	 * \brief Add算子的tiling(分块)策略实现
14	 *
15	 * 本文件提供了tiling逻辑，将大型计算任务划分为较小的块，以便在AI Core上高效并行执行。
16	 * Tiling对于最大化NPU利用率和性能至关重要。
17	 */
18	
19	#include "log/log.h"
20	#include "util/math_util.h"
21	#include "util/platform_util.h"
22	#include "op_host/tiling_util.h"
23	#include "op_host/tiling_templates_registry.h"
24	#include "../op_kernel/add_example_tiling_data.h"
25	#include "../op_kernel/add_example_tiling_key.h"
26	
27	namespace optiling {
28	
29	using namespace Ops::Cv::OpTiling;
30	
31	// 矢量系统缓冲区大小为0
32	constexpr uint32_t WS_SYS_SIZE = 0U;
33	// 输入shape的维度限制为4
34	constexpr int32_t DIMS_LIMIT = 4;
35	
36	// 维度索引常量定义
37	constexpr uint32_t INDEXZERO = 0;
38	constexpr uint32_t INDEXONE = 1;
39	constexpr uint32_t INDEXTWO = 2;
40	constexpr uint32_t INDEXTHREE = 3;
41	
42	// 缓冲区数量常量(字节)
43	constexpr int64_t BUFFER_NUM = 6;
44	// 类型大小常量(字节)
45	constexpr int64_t TYPE_SIZE = 4;
46	
47	// Add编译信息结构体
48	struct AddExampleCompileInfo {};
49	
50	// 标量形状常量{1}
51	static const gert::Shape g_vec_1_shape = {1};
52	
53	/*!
54	 * \brief 确保标量shape转换为{1}以保持一致性
55	 *
56	 * 对于标量输入，需要将其转换为1维张量以确保处理的一致性。
57	 *
58	 * \param in_shape 要检查的输入shape
59	 * \return 如果输入是标量则返回{1}，否则返回原shape的引用
60	 */
61	inline const gert::Shape& EnsureNotScalar(const gert::Shape& in_shape)
62	{
63	    if (in_shape.IsScalar()) {
64	        return g_vec_1_shape;
65	    }
66	    return in_shape;
67	}
68	
69	/*!
70	 * \brief 获取平台信息，包括UB(统一缓冲区)大小和AI Core数量
71	 *
72	 * 该函数查询平台以获取硬件资源信息，这对于确定最优tiling策略至关重要。
73	 *
74	 * \param context 指向tiling上下文的指针
75	 * \param ubSize 输出参数：UB大小(字节)
76	 * \param coreNum 输出参数：可用AI Core数量
77	 * \return 如果成功获取平台信息则返回ge::GRAPH_SUCCESS
78	 */
79	static ge::graphStatus GetPlatformInfo(gert::TilingContext* context, uint64_t& ubSize, int64_t& coreNum)
80	{
81	    // 获取平台信息指针
82	    fe::PlatFormInfos* platformInfoPtr = context->GetPlatformInfo();
83	    OP_CHECK_NULL_WITH_CONTEXT(context, platformInfoPtr);
84	
85	    // 创建AscendC平台对象
86	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
87	
88	    // 获取AI Core数量
89	    coreNum = ascendcPlatform.GetCoreNumAiv();
90	    OP_CHECK_IF(coreNum == 0, OP_LOGE(context, "coreNum is 0"), return ge::GRAPH_FAILED);
91	
92	    // 获取UB(统一缓冲区)大小
93	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
94	    OP_CHECK_IF(ubSize == 0, OP_LOGE(context, "ubSize is 0"), return ge::GRAPH_FAILED);
95	
96	    return ge::GRAPH_SUCCESS;
97	}
98	
99	/*!
100	 * \brief 从输入输出张量获取shape和属性信息
101	 *
102	 * 该函数检索并验证张量shape和数据类型。它确保：
103	 * - 所有张量都有4维shape
104	 * - 数据类型是支持的(FLOAT或INT32)
105	 * - 计算总元素数量
106	 *
107	 * \param context 指向tiling上下文的指针
108	 * \param totalIdx 输出参数：要处理的总元素数量
109	 * \param dataType 输出参数：输入张量的数据类型
110	 * \return 如果成功获取和验证shape信息则返回ge::GRAPH_SUCCESS
111	 */
112	static ge::graphStatus GetShapeAttrsInfo(gert::TilingContext* context, int64_t& totalIdx, ge::DataType& dataType)
113	{
114	    // 获取输入x的shape信息
115	    auto inputX = context->GetInputShape(0);
116	    OP_CHECK_NULL_WITH_CONTEXT(context, inputX);
117	
118	    // 如果输入shape是标量，转换为{1}，否则保持原shape不变
119	    auto inputShapeX = EnsureNotScalar(inputX->GetStorageShape());
120	
121	    // 获取输入y的shape信息
122	    auto inputY = context->GetInputShape(1);
123	    OP_CHECK_NULL_WITH_CONTEXT(context, inputY);
124	    auto inputShapeY = EnsureNotScalar(inputY->GetStorageShape());
125	
126	    // 获取输出z的shape信息
127	    auto outZ = context->GetOutputShape(0);
128	    OP_CHECK_NULL_WITH_CONTEXT(context, outZ);
129	    auto outShapeZ = EnsureNotScalar(outZ->GetStorageShape());
130	
131	    // shape校验：确保所有张量都是4维
132	    OP_CHECK_IF(inputShapeX.GetDimNum() != DIMS_LIMIT || inputShapeY.GetDimNum() != DIMS_LIMIT ||
133	                    outShapeZ.GetDimNum() != DIMS_LIMIT,
134	                OP_LOGE(context, "AddExample: inputx,inputy,outputz shape dim = %zu, %zu, %zu, should be equal 4",
135	                        inputShapeX.GetDimNum(), inputShapeY.GetDimNum(), outShapeZ.GetDimNum()),
136	                return ge::GRAPH_FAILED);
137	
138	    // 获取shape的维度值
139	    totalIdx = inputShapeX.GetShapeSize();
140	
141	    // 数据类型校验
142	    const std::set<ge::DataType> supportedDtype = {ge::DT_FLOAT, ge::DT_INT32};
143	    auto inputDesc = context->GetInputDesc(0);
144	    OP_CHECK_NULL_WITH_CONTEXT(context, inputDesc);
145	    dataType = inputDesc->GetDataType();
146	
147	    if (supportedDtype.count(dataType) == 0) {
148	        OP_LOGE(context, "invalid dtype");
149	        return ge::GRAPH_FAILED;
150	    }
151	
152	    return ge::GRAPH_SUCCESS;
153	}
154	
155	/*!
156	 * \brief 获取算子执行所需的工作空间大小
157	 *
158	 * 工作空间是计算期间使用的额外内存。对于Add算子，
159	 * 不需要工作空间，因此大小设置为0。
160	 *
161	 * \param context 指向tiling上下文的指针
162	 */
163	
164	static ge::graphStatus GetWorkspaceSize(gert::TilingContext* context)
165	{
166	    // 获取工作空间大小数组
167	    size_t* currentWorkspace = context->GetWorkspaceSizes(1);
168	    OP_CHECK_NULL_WITH_CONTEXT(context, currentWorkspace);
169	    currentWorkspace[0] = WS_SYS_SIZE;
170	    return ge::GRAPH_SUCCESS;
171	}
172	
173	/*!
174	 * \brief Add算子的主tiling函数
175	 *
176	 * 该函数计算最优的tiling策略：
177	 * 1. 查询平台信息(UB大小、AI Core数量)
178	 * 2. 检索shape和属性信息
179	 * 3. 计算Core tiling：将工作划分到多个AI Core以实现并行
180	 * 4. 计算UB tiling：根据可用的UB内存在每个Core内划分工作
181	 * 5. 根据数据类型设置tiling key(FLOAT和INT32有不同的tiling策略)
182	 *
183	 * Tiling数据存储在AddExampleTilingData结构中，将被传递给kernel。
184	 *
185	 * \param context 指向tiling上下文的指针
186	 * \return 如果成功计算tiling策略则返回ge::GRAPH_SUCCESS
187	 */
188	// tiling 分发入口
189	static ge::graphStatus AddExampleTilingFunc(gert::TilingContext* context)
190	{
191	    // 1、获取平台运行信息
192	    uint64_t ubSize;
193	    int64_t coreNum;
194	    OP_CHECK_IF(GetPlatformInfo(context, ubSize, coreNum) != ge::GRAPH_SUCCESS,
195	                OP_LOGE(context, "GetPlatformInfo error"), return ge::GRAPH_FAILED);
196	
197	    // 2、获取shape、属性信息
198	    int64_t totalIdx;
199	    ge::DataType dataType;
200	    OP_CHECK_IF(GetShapeAttrsInfo(context, totalIdx, dataType) != ge::GRAPH_SUCCESS,
201	                OP_LOGE(context, "GetShapeAttrsInfo error"), return ge::GRAPH_FAILED);
202	
203	    // 3、获取WorkspaceSize信息
204	    OP_CHECK_IF(GetWorkspaceSize(context) != ge::GRAPH_SUCCESS, OP_LOGE(context, "GetWorkspaceSize error"),
205	                return ge::GRAPH_FAILED);
206	
207	    // 4、设置tiling信息
208	    AddExampleTilingData* tiling = context->GetTilingData<AddExampleTilingData>();
209	    OP_CHECK_NULL_WITH_CONTEXT(context, tiling);
210	
211	    // 初始化tiling数据为0
212	    OP_CHECK_IF(memset_s(tiling, sizeof(AddExampleTilingData), 0, sizeof(AddExampleTilingData)) != EOK,
213	                OP_LOGE(context, "set tiling data error"), return ge::GRAPH_FAILED);
214	
215	    // 优先做核切分，尽量用更多的核并行计算
216	    // 计算每个AI Core处理的元素数量
217	    tiling->totalNum = totalIdx;
218	    tiling->blockFactor = Ops::Base::CeilDiv(totalIdx, coreNum);
219	    int64_t usedCoreNum = Ops::Base::CeilDiv(totalIdx, tiling->blockFactor);
220	
221	    // 计算ub切分，考虑最大同时使用的ub tensor数量，计算单个ub tensor可用大小
222	    // 当前场景，2输入和1输出，考虑使能db，共需要6块ub tensor
223	    int64_t ubCanUse = static_cast<int64_t>(ubSize);
224	    int64_t ubBlockSize = Ops::Base::GetUbBlockSize(context);
225	    tiling->ubFactor = Ops::Base::FloorAlign(Ops::Base::FloorDiv((ubCanUse / TYPE_SIZE), BUFFER_NUM), ubBlockSize);
226	
227	    // 设置使用的AI Core数量
228	    context->SetBlockDim(usedCoreNum);
229	
230	    // 根据数据类型设置tiling key
231	    uint64_t tilingKey = 0;
232	    // 区分dtype走不同得tiling key分支.
233	    if (dataType == ge::DT_FLOAT) {
234	        // 浮点数据类型使用mode 0的tiling key
235	        tilingKey = GET_TPL_TILING_KEY(ELEMENTWISE_TPL_SCH_MODE_0);
236	        context->SetTilingKey(tilingKey);
237	    } else if (dataType == ge::DT_INT32) {
238	        // 32位整数类型使用mode 1的tiling key
239	        tilingKey = GET_TPL_TILING_KEY(ELEMENTWISE_TPL_SCH_MODE_1);
240	        context->SetTilingKey(tilingKey);
241	    } else {
242	        OP_LOGE(context, "get dtype error");
243	        return ge::GRAPH_FAILED;
244	    }
245	
246	    return ge::GRAPH_SUCCESS;
247	}
248	
249	/*!
250	 * \brief 解析Add算子的tiling信息
251	 *
252	 * 该函数在模型加载期间被调用，以解析任何静态tiling信息。
253	 * 对于Add算子，不需要静态tiling，因此直接返回成功。
254	 *
255	 * \param context 指向tiling解析上下文的指针
256	 * \return ge::GRAPH_SUCCESS
257	 */
258	
259	static ge::graphStatus TilingParseForAddExample([[maybe_unused]] gert::TilingParseContext* context)
260	{
261	    return ge::GRAPH_SUCCESS;
262	}
263	
264	// tiling注册入口
265	// 将tiling函数、tiling解析函数和编译信息注册到系统中
266	IMPL_OP_OPTILING(AddExample).Tiling(AddExampleTilingFunc).TilingParse<AddExampleCompileInfo>(TilingParseForAddExample);
267	} // namespace optiling
